def remove_file(path):
    """Remove file at specified path."""

    # early exit in 'dry run' mode
    if build_option('extended_dry_run'):
        dry_run_msg("file %s removed" % path, silent=build_option('silent'))
        return

    try:
        # note: file may also be a broken symlink...
        if os.path.exists(path) or os.path.islink(path):
            os.remove(path)
    except OSError as err:
        raise EasyBuildError("Failed to remove file %s: %s", path, err)

def empty_dir(path):
    """Empty directory at specified path, keeping directory itself intact."""
    # early exit in 'dry run' mode
    if build_option('extended_dry_run'):
        dry_run_msg(f"directory {path} emptied", silent=build_option('silent'))
        return

    if os.path.exists(path):
        try:
            for item in os.listdir(path):
                subpath = os.path.join(path, item)
                if os.path.isfile(subpath) or os.path.islink(subpath):
                    remove_file(subpath)
                elif os.path.isdir(subpath):
                    remove_dir(subpath)
            _log.info(f"Path {path} successfully emptied.")
        except OSError as err:
            raise EasyBuildError(f"Failed to empty directory {path}: {err}")

def clean_dir(path):
    """
    Try to remove directory at specified path.
    If that fails, empty directory instead.
    """
    try:
        remove_dir(path)
    except EasyBuildError as err:
        _log.debug(f"Removing directory {path} failed, will try to empty it instead: {err}")
        empty_dir(path)

def remove(paths):
    """
    Remove single file/directory or list of files and directories

    :param paths: path(s) to remove
    """
    if isinstance(paths, str):
        paths = [paths]

    _log.info("Removing %d files & directories", len(paths))

    for path in paths:
        if os.path.isfile(path) or os.path.islink(path):
            remove_file(path)
        elif os.path.isdir(path):
            remove_dir(path)
        else:
            raise EasyBuildError("Specified path to remove is not an existing file or directory: %s", path)

def get_cwd(must_exist=True):
    """
    Retrieve current working directory
    """
    try:
        cwd = os.getcwd()
    except FileNotFoundError as err:
        if must_exist is True:
            raise EasyBuildError(CWD_NOTFOUND_ERROR)

        _log.debug("Failed to determine current working directory, but proceeding anyway: %s", err)
        cwd = None

    return cwd

