    python_ver = '%d.%d' % (python_maj_ver, python_min_ver)
    _log.info("Found Python version %s", python_ver)

    if python_maj_ver == 3:
        if python_min_ver < 6:
            raise EasyBuildError("Python 3.6 or higher is required, found Python %s", python_ver)
