def get_arch_prefix():
    """Return the architecture prefix"""
    arch = get_cpu_architecture()
    if arch == POWER:
        if get_cpu_family() == POWER_LE:
            return 'powerpc64le'
        else:
            return 'powerpc64'
    elif arch == RISCV64:
        return 'riscv64'
    else:
        return arch.lower()

