    Configure,
    /// Compilation failed.
    Compile,
    /// Linking failed.
    Link,
    /// The package test suite failed.
    Test,
    /// The install step failed.
    Install,
    /// EasyBuild's sanity check failed: it built but is not usable.
    Sanity,
    /// The job ran out of memory, disk, or another quota.
    Resource,
    /// The job exceeded its time limit.
