fn count_percent_conversions(fmt: &str) -> usize {
    let b = fmt.as_bytes();
    let mut i = 0;
    let mut n = 0;
    while i + 1 < b.len() {
        if b[i] == b'%' {
            match b[i + 1] {
                b'%' => {
                    i += 2;
                    continue;
                }
                b's' | b'd' => {
                    n += 1;
                    i += 2;
