    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "{}:{}:{}: {} {}",
            self.line,
            self.column,
            self.code,
            self.message,
            if self.mechanical {
                "(mechanical)"
            } else {
                "(manual break)"
            }
        )
    }
}

