pub fn changed(
    before: &BTreeMap<ModuleKey, InputHash>,
    after: &BTreeMap<ModuleKey, InputHash>,
) -> Vec<ModuleKey> {
    let mut out: Vec<ModuleKey> = Vec::new();
    for (key, now) in after {
        match before.get(key) {
            Some(then) if then.hash == now.hash => {}
            _ => out.push(key.clone()),
        }
    }
    out.sort();
    out
}

