            versions.iter().map(|s| s.as_str()),
            &policy_toolchain.version,
            explicit_baseline_version,
        )?;
        Ok(base_cands
            .iter()
            .filter(|c| c.toolchain.name == policy_toolchain.name && c.toolchain.version == bv)
