fn validate_bump_fields(
    name: &str,
    format: Option<ForeignFormat>,
    package_config: &[PathBuf],
    profile: &str,
) -> Result<(), PackageCatalogError> {
    if format.is_some() {
        return Err(PackageCatalogError::IncompatibleBumpField {
            name: name.to_string(),
            field: "format".into(),
        });
    }
    if !package_config.is_empty() {
        return Err(PackageCatalogError::IncompatibleBumpField {
            name: name.to_string(),
            field: "package_config".into(),
        });
    }
    if profile != "default" {
        return Err(PackageCatalogError::IncompatibleBumpField {
            name: name.to_string(),
            field: "profile".into(),
        });
    }
    Ok(())
}

fn resolve_path(base_directory: Option<&Path>, path: &str) -> PathBuf {
    let path = Path::new(path);
    if path.is_absolute() {
        path.to_path_buf()
    } else if let Some(base) = base_directory {
        base.join(path)
    } else {
        path.to_path_buf()
    }
}

fn provider_key(name: &str, version: Option<&str>) -> String {
    format!(
        "{}@{}",
        package_identity(name),
        version.unwrap_or("").trim()
    )
}

fn package_identity(name: &str) -> String {
    name.chars()
        .filter(|character| character.is_ascii_alphanumeric())
        .flat_map(char::to_lowercase)
        .collect()
}

fn version_suffix(version: Option<&str>) -> String {
    match version {
        Some(version) if !version.is_empty() => format!(" {version}"),
        _ => String::new(),
    }
}

//! Recursive package-closure planner and aggregate bundle writer.
//!
//! Closes a root foreign package plan over robot candidates, optional catalog
//! overrides, and ordered local source roots (EasyBuild / conda-forge / Spack / Cargo).
//! Compatible robot candidates win. Holes resolve robot-first, then catalog
//! overrides, then EasyBuild cross-generation bump, then an unambiguous foreign
//! recipe. Package names never appear as control flow.
//!
