fn overlay_exts_default_options(plan: &PackagePlan, kind: LanguageBundleKind) -> String {
    // An R bundle needs to know where CRAN keeps sources, current and archived,
    // and how a release tarball is named. Without it every extension is an
    // unresolvable download.
    if matches!(kind, LanguageBundleKind::R) {
        if plan.overlay_extensions.is_empty() {
            return String::new();
        }
        return "exts_default_options = {\n    'source_urls': [\n        \
                'https://cran.r-project.org/src/contrib/',\n        \
                'https://cran.r-project.org/src/contrib/Archive/%(name)s',\n    ],\n    \
                'sources': ['%(name)s_%(version)s.tar.gz'],\n}\n\n"
            .to_string();
    }
    // The prepended PYTHONPATH is what lets one extension import another it was
    // just installed beside. An R bundle installs into the R library path and
    // has no use for it.
    if !matches!(kind, LanguageBundleKind::Python) {
        return String::new();
    }
    if plan.overlay_extensions.is_empty() && !mesonpy_backend(plan) {
        return String::new();
    }
    "exts_default_options = {\n    'preinstallopts': 'export PYTHONPATH=%(installdir)s/lib/python%(pyshortver)s/site-packages${PYTHONPATH:+:$PYTHONPATH} && ',\n}\n\n".to_string()
}

fn mesonpy_backend(plan: &PackagePlan) -> bool {
    plan.build.build_systems.iter().any(|hint| {
        let hint = hint.to_ascii_lowercase();
        hint.contains("mesonpy") || hint == "meson"
    })
}

fn mesonpy_preinstallopts() -> String {
    format!(
        "{}export PYTHONPATH=%(installdir)s/lib/python%(pyshortver)s/site-packages${{PYTHONPATH:+:$PYTHONPATH}} && ",
        crate::cargo::eessi_cargo_host_isolation()
    )
}

fn render_plain_ext(name: &str, version: &str, checksum: Option<&str>) -> String {
    match checksum {
        Some(checksum) => format!(
            "('{}', '{}', {{\n    'checksums': ['{}'],\n}})",
            escape_single(name),
            escape_single(version),
            escape_single(checksum)
        ),
        None => format!("('{}', '{}')", escape_single(name), escape_single(version)),
    }
}

/// Prefer conventional EasyBuild key order for common toolchainopts.

fn render_toolchain_options(options: &BTreeMap<String, bool>) -> String {
    const PREFERRED: &[&str] = &["usempi", "openmp", "pic", "opt", "debug"];
    let mut names = options.keys().cloned().collect::<Vec<_>>();
    names.sort_by(|left, right| {
        let left_rank = PREFERRED
            .iter()
            .position(|name| name == left)
            .unwrap_or(PREFERRED.len());
        let right_rank = PREFERRED
            .iter()
            .position(|name| name == right)
            .unwrap_or(PREFERRED.len());
        left_rank.cmp(&right_rank).then_with(|| left.cmp(right))
    });
    names
        .into_iter()
        .filter_map(|name| {
            options
                .get(&name)
                .map(|enabled| format!("'{name}': {}", python_bool(*enabled)))
        })
        .collect::<Vec<_>>()
        .join(", ")
}

struct SourceBlock {
    prelude: String,
    sources: String,
    checksums: String,
}

fn render_easyconfig_parameters(parameters: &BTreeMap<String, EasyconfigValue>) -> String {
    if parameters.is_empty() {
        return String::new();
    }
    let mut rendered = parameters
        .iter()
        .map(|(name, value)| match value {
            EasyconfigValue::Concat(fragments) => render_string_concat(name, &fragments.concat),
            _ => format!("{name} = {}", render_easyconfig_value(value, 0)),
        })
        .collect::<Vec<_>>()
        .join("\n");
    rendered.push_str("\n\n");
    rendered
}

fn render_string_concat(name: &str, fragments: &[String]) -> String {
    let mut fragments = fragments.iter();
    let Some(first) = fragments.next() else {
        return format!("{name} = ''");
    };
    let mut rendered = format!("{name} = '{}'", escape_single(first));
    for fragment in fragments {
        rendered.push_str(&format!("\n{name} += '{}'", escape_single(fragment)));
    }
    rendered
}

fn render_easyconfig_value(value: &EasyconfigValue, indentation: usize) -> String {
    match value {
        EasyconfigValue::Bool(value) => python_bool(*value).into(),
        EasyconfigValue::Integer(value) => value.to_string(),
        EasyconfigValue::String(value) => format!("'{}'", escape_single(value)),
        EasyconfigValue::List(values) => render_easyconfig_sequence(values, indentation),
        EasyconfigValue::Concat(fragments) => {
            format!("'{}'", escape_single(&fragments.concat.join("")))
        }
        EasyconfigValue::Table(values) => render_easyconfig_table(values, indentation),
    }
}

fn render_easyconfig_sequence(values: &[EasyconfigValue], indentation: usize) -> String {
    if values.is_empty() {
        return "[]".into();
    }
    let item_indentation = indentation + 4;
    let prefix = " ".repeat(item_indentation);
    let suffix = " ".repeat(indentation);
    let items = values
        .iter()
        .map(|value| {
            format!(
                "{prefix}{},",
                render_easyconfig_value(value, item_indentation)
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!("[\n{items}\n{suffix}]")
}

fn render_easyconfig_table(
    values: &BTreeMap<String, EasyconfigValue>,
    indentation: usize,
) -> String {
    if values.is_empty() {
        return "{}".into();
    }
    let item_indentation = indentation + 4;
    let prefix = " ".repeat(item_indentation);
    let suffix = " ".repeat(indentation);
    let items = values
        .iter()
        .map(|(key, value)| {
            format!(
                "{prefix}'{}': {},",
                escape_single(key),
                render_easyconfig_value(value, item_indentation)
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!("{{\n{items}\n{suffix}}}")
}

