fn infer_foreign_package_name(path: &Path, root: &Path, format: ForeignFormat) -> Option<String> {
    if format == ForeignFormat::CondaForge {
        if let Ok(text) = std::fs::read_to_string(path) {
            if let Some(name) = infer_conda_package_name(&text) {
                return Some(name);
            }
        }
    }
    infer_package_name_from_path(path, root, format)
}

fn infer_conda_package_name(text: &str) -> Option<String> {
    let mut in_package = false;
    for line in text.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        let indented = line.starts_with(' ') || line.starts_with('\t');
        if !in_package {
            if !indented && trimmed == "package:" {
                in_package = true;
            }
            continue;
        }
        if !indented {
            return None;
        }
        let Some(value) = trimmed.strip_prefix("name:") else {
            continue;
        };
        let value = value
            .split('#')
            .next()
            .unwrap_or_default()
            .trim()
            .trim_matches(['\'', '"']);
        if !value.is_empty()
            && value
                .chars()
                .all(|character| character.is_ascii_alphanumeric() || "-_.+".contains(character))
        {
            return Some(value.to_string());
        }
        return None;
    }
    None
}

fn infer_package_name_from_path(path: &Path, root: &Path, format: ForeignFormat) -> Option<String> {
    let parent = path.parent()?;
    let package_dir = match format {
        ForeignFormat::CondaForge
            if parent
                .file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| name.eq_ignore_ascii_case("recipe")) =>
        {
            parent.parent()?
        }
        ForeignFormat::CondaForge
        | ForeignFormat::Spack
        | ForeignFormat::Pypi
        | ForeignFormat::Cran
        | ForeignFormat::Cargo
        | ForeignFormat::Luarocks
        | ForeignFormat::Raku => parent,
    };
    let package_dir = if package_dir == root {
        root.file_name()?.to_str()?
    } else {
        package_dir.file_name()?.to_str()?
    };
    let name = package_dir
        .strip_suffix("-feedstock")
        .unwrap_or(package_dir);
    (!name.is_empty()).then(|| name.to_string())
}

fn load_package_config_layers(
    paths: &[PathBuf],
) -> Result<Vec<PackageConfigLayer>, PackageSourceError> {
    paths
        .iter()
        .map(|path| {
            PackageConfigLayer::from_path(path).map_err(|error| {
                PackageSourceError::PackageConfig(path.display().to_string(), error.to_string())
            })
        })
        .collect()
}

fn provider_name_for_foreign(name: &str, layers: &[PackageConfigLayer]) -> String {
    let mut provider = name.to_string();
    for layer in layers {
        if let Some(alias) = layer.dependencies.as_ref().and_then(|dependencies| {
            dependencies.aliases.iter().find_map(|(foreign, alias)| {
                (package_identity(foreign) == package_identity(&provider)).then_some(alias)
            })
        }) {
            provider = alias.provider().to_string();
        }
        if let Some(name) = layer
            .package
            .as_ref()
            .and_then(|package| package.name.as_ref())
        {
            provider.clone_from(name);
        }
    }
    provider
}

