fn adopt_moduleclass_from_tree(plan: &mut PackagePlan, candidates: &[crate::domain::Candidate]) {
    let identity = crate::provides::overlay_package_identity(&plan.package.name);
    let Some(existing) = candidates
        .iter()
        .filter(|candidate| {
            crate::provides::overlay_package_identity(&candidate.name) == identity
                && candidate.moduleclass.is_some()
        })
        .max_by(|left, right| crate::version::cmp_version(&left.version, &right.version))
        .and_then(|candidate| candidate.moduleclass.clone())
    else {
        return;
    };
    if plan.build.moduleclass.as_deref() == Some(existing.as_str()) {
        return;
    }
    plan.residuals.push(Residual {
        id: "moduleclass:from-tree".into(),
        stage: ResidualStage::Resolve,
        category: "moduleclass".into(),
        severity: ResidualSeverity::Mechanical,
        summary: format!(
            "moduleclass {existing} taken from the recipe this tree already carries for {}",
            plan.package.name
        ),
        evidence: None,
        provenance: None,
    });
    plan.build.moduleclass = Some(existing);
    plan.residuals.retain(|residual| residual.id != "moduleclass:inferred");
}

/// Say plainly that a moduleclass was inferred rather than known.
///
/// Upstream's class for a package is a judgement: `einops` is classed `math`
/// and `fonttools

fn note_inferred_moduleclass(plan: &mut PackagePlan) {
    if plan
        .residuals
        .iter()
        .any(|residual| residual.id == "moduleclass:from-tree")
    {
        return;
    }
    let Some(moduleclass) = plan.build.moduleclass.clone() else {
        return;
    };
    plan.residuals.push(Residual {
        id: "moduleclass:inferred".into(),
        stage: ResidualStage::Resolve,
        category: "moduleclass".into(),
        severity: ResidualSeverity::Judgment,
        summary: format!(
            "moduleclass {moduleclass} is inferred from the package's own classifiers;              this tree carries no other recipe for {} to take it from",
            plan.package.name
        ),
        evidence: None,
        provenance: None,
    });
}

/// The `binutils` a GCCcore-level recipe builds against.
///
/// EasyBuild's GCCcore level exists so that a package can be built once for a
/// whole compiler generation, and every recipe there carries
/// `builddependencies = [('binutils', ...)]`: tqdm at GCCcore-14.2.0 names
/// binutils 2.42, as does every one of its neighbours. A generated recipe
/// without it is not the recipe a maintainer would accept.

fn add_gcccore_binutils(plan: &mut PackagePlan) {
    if !plan.build.toolchain.name.eq_ignore_ascii_case("GCCcore") {
        return;
    }
    if plan
        .dependencies
        .iter()
        .any(|dependency| dependency.name.eq_ignore_ascii_case("binutils"))
    {
        return;
    }
    plan.dependencies.push(DependencyIntent {
        id: format!("toolchain:{}:binutils", plan.build.toolchain.name),
        name: "binutils".into(),
        eb_name: Some("binutils".into()),
        // The version is the generation's own, which the solve picks from the
        // candidates at this level.
        constraint: None,
        toolchain: Some(plan.build.toolchain.clone()),
        roles: vec![DependencyRole::Build],
        condition: ConditionExpr::Always,
        virtual_capability: None,
        solver_excluded: false,
        provenance: Vec::new(),
    });
}

fn pin_binutils_to_gcccore(
    plan: &mut PackagePlan,
    candidates: &[crate::domain::Candidate],
    hierarchy_fixture: Option<&Path>,
) {
    let Ok(hierarchy) =
        hierarchy_for_with_tree(&plan.build.toolchain, hierarchy_fixture, candidates)
    else {
        return;
    };
    let Some(gcccore) = hierarchy
        .members
        .iter()
        .find(|toolchain| toolchain.name.eq_ignore_ascii_case("GCCcore"))
        .cloned()
    else {
        return;
    };
    for dependency in &mut plan.dependencies {
        if dependency.name.eq_ignore_ascii_case("binutils") {
            dependency.toolchain = Some(gcccore.clone());
        }
    }
}

